using System;using System.Linq;using System.IO;using System.Collections.Generic;using System.Globalization;using System.Text.Json;using Rizan.Portfolio;
var bars=File.ReadLines(args[0]).Skip(1).Select(line=>{var p=line.Split(',');return new BtcBar(DateTimeOffset.FromUnixTimeSeconds(long.Parse(p[0])).UtcDateTime,double.Parse(p[1],CultureInfo.InvariantCulture),double.Parse(p[2],CultureInfo.InvariantCulture),double.Parse(p[3],CultureInfo.InvariantCulture),double.Parse(p[4],CultureInfo.InvariantCulture),int.Parse(p[5]));}).ToList();
var start=new DateTime(2026,9,30,17,0,0,DateTimeKind.Utc);var end=new DateTime(2026,10,20,17,0,0,DateTimeKind.Utc);var live=new DateTime(2026,10,9,17,0,0,DateTimeKind.Utc);
var hourly=bars.Where(b=>b.At.AddHours(1)<=end).ToList();var four=BtcCore.Aggregate(hourly,240).Where(b=>b.At.AddHours(4)<=end).ToList();var all=BtcCore.Signals(hourly,four);
var rows=all.Values.Where(s=>s.At>=start&&s.At<end).OrderBy(s=>s.At).Select(s=>new{utc=s.At,wib=s.At.AddHours(7).ToString("yyyy-MM-dd HH:mm:ss"),direction=s.Side==1?"BUY":"SELL",s.Atr,s.Reference,since_10_oct_wib=s.At>=live,weekday=s.At.DayOfWeek!=DayOfWeek.Saturday&&s.At.DayOfWeek!=DayOfWeek.Sunday,assumed_weekly_entry_cutoff_pass=s.At.DayOfWeek!=DayOfWeek.Saturday&&s.At.DayOfWeek!=DayOfWeek.Sunday&&(s.At.DayOfWeek!=DayOfWeek.Friday||s.At.Hour<21),native_broker_session_checked=false,actual_fill_asserted=false}).ToArray();
Directory.CreateDirectory(args[1]);File.WriteAllText(Path.Combine(args[1],"BTC_SOURCE_SIGNALS.json"),JsonSerializer.Serialize(new{source="Unchanged frozen V1.3.0 BtcCore.cs",period_start_utc=start,period_end_exclusive_utc=end,indicator_seed_start=hourly[0].At,hourly_rows=hourly.Count,four_hourly_rows=four.Count,candidate_signals=rows.Length,candidate_signals_since10=rows.Count(x=>x.since_10_oct_wib),assumed_calendar_eligible=rows.Count(x=>x.assumed_weekly_entry_cutoff_pass),signals=rows,warning="Signal audit only. No broker quote/chase/margin/shared state/order execution replay. Calendar is an assumption; native uses broker schedule."},new JsonSerializerOptions{WriteIndented=true}));
Console.WriteLine(JsonSerializer.Serialize(new{btc_signals=rows.Length,btc_since10=rows.Count(x=>x.since_10_oct_wib),rows}));
